/* =============================================================================
   INV-04 — Canal de ingestión por email.
   Todo el color sale de los tokens de `:root` (design-system §1): aquí no hay ni
   un hex ni un rgb(). Nota de tokens que faltan:
     · No existe un token de blanco puro. Para la superficie de las tarjetas se usa
       `--bw-warm-cream`, el blanco cálido del sistema, que es el más cercano.
     · Para el texto sobre el azul primario se usa `--bw-cold-white` (opaco), en vez
       del blanco al 90 % de la familia `--bw-on-dark-*`.
   ========================================================================== */

/* La raíz cuelga DIRECTA de `.bwcnt` (overflow: hidden): el scroll es suyo. */
.screen {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  padding: var(--bw-screen-pad);
  background: var(--bw-cold-white);
}

/* ── Cabecera ─────────────────────────────────────────────────────────────── */

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-eyebrow);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-steel-mist);
  margin-bottom: 6px;
  flex-shrink: 0;
}

.title {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
  margin-bottom: 4px;
  flex-shrink: 0;
}

.subtitle {
  font-size: var(--bw-size-subtitle);
  color: var(--bw-steel-mist);
  line-height: 1.6;
  max-width: 600px;
  margin-bottom: 28px;
  flex-shrink: 0;
}

/* Aviso de solo lectura del EDITOR: brass informativo, nunca rojo. */
.readOnly {
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-brass-border);
  border-radius: var(--bw-radius-hamburger);
  padding: 12px 14px;
  font-size: var(--bw-size-subtitle);
  color: var(--bw-steel-mist);
  line-height: 1.6;
}

/* ── Mensajes de la pantalla ──────────────────────────────────────────────── */

.alert {
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius-hamburger);
  padding: 10px 14px;
  font-size: var(--bw-size-input);
  color: var(--bw-error-text);
  line-height: 1.5;
  margin-bottom: 16px;
  flex-shrink: 0;
}

.status {
  margin-top: 12px;
  padding: 10px 14px;
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: var(--bw-radius-hamburger);
  font-size: var(--bw-size-input);
  color: var(--bw-success-dark);
  line-height: 1.5;
}

/* ── Tarjetas ─────────────────────────────────────────────────────────────── */

.card {
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  padding: 24px;
  margin-bottom: 20px;
  /* La pantalla es una columna flex con scroll: las tarjetas no se aplastan. */
  flex-shrink: 0;
}

.cardTitle {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-label);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-steel-mist);
  margin-bottom: 16px;
}

/* ── Dirección de ingestión ───────────────────────────────────────────────── */

.addressRow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.addressField {
  flex: 1;
  min-width: 0;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius-hamburger);
  padding: var(--bw-pad-input);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  text-overflow: ellipsis;
}

.copy {
